import {
  FileTree,
  useFileTree,
  FileTreeHeader,
  FileTreeTitle,
  FileTreeActions,
  FileTreeContent,
} from "@/registry/erbium/blocks/file-tree";
import { Button } from "@/registry/erbium/ui/button";
import { paths } from "../examples/paths";
export default function Example() {
  const { model } = useFileTree({
    paths,
    initialExpansion: "open",
    gitStatus: [
      { path: "src/blocks/file-view.tsx", status: "added" },
      { path: "src/styles/surfaces.css", status: "modified" },
    ],
  });
  return (
    <FileTree model={model} className="w-80" aria-label="Changed project files">
      <FileTreeHeader>
        <FileTreeTitle>Changes</FileTreeTitle>
        <FileTreeActions>
          <Button variant="ghost" size="xs" onClick={() => model.add("src/blocks/file-tree.tsx")}>
            Add file
          </Button>
        </FileTreeActions>
      </FileTreeHeader>
      <FileTreeContent />
    </FileTree>
  );
}
